insert into public.changelog (datum, categorie, module, titel, omschrijving) values
  ('2026-09-14','verbeterd','Uren','Uren fiatteren op de telefoon gaat nu per week',
   'Het fiatteerscherm op de telefoon toont de uren voortaan per medewerker per week in plaats van per project, met een knop die de hele week in één keer akkoord geeft. De bewakingscode staat boven de week: je ziet in één oogopslag hoeveel uur er op welke code is geboekt, en met één tik verplaats je alle uren van een code naar een andere. Gewerkte uren zonder bewakingscode kleuren oranje en houden de week tegen, zodat ze niet ongemerkt doorschuiven; verlof en ATV horen geen code te hebben en blijven met rust. Uren uit dezelfde week die bij een andere beoordelaar liggen staan er grijs bij, zodat het weektotaal klopt.'),
  ('2026-09-14','verbeterd','Uren','Teamleider van de ploeg keurt mee',
   'Staat er op een opdracht geen teamleider, dan gaan de uren nu eerst naar de teamleider van de ploeg waar de medewerker in zit, en daarna pas naar de projectleider. Daarmee komt de eerste controle terecht bij degene die het werk heeft gezien. Je eigen uren keur je nooit goed, en is er ook geen ploegteamleider, dan blijft het zoals het was: rechtstreeks naar de projectleider.');
